def memory():
 try:
  class PMC(ctypes.Structure):
   _fields_=[('cb',ctypes.c_ulong),('PageFaultCount',ctypes.c_ulong)]+[(n,ctypes.c_size_t) for n in ['PeakWorkingSetSize','WorkingSetSize','QuotaPeakPagedPoolUsage','QuotaPagedPoolUsage','QuotaPeakNonPagedPoolUsage','QuotaNonPagedPoolUsage','PagefileUsage','PeakPagefileUsage']]
  z=PMC();z.cb=ctypes.sizeof(z);ctypes.windll.kernel32.GetCurrentProcess.restype=ctypes.c_void_p;h=ctypes.windll.kernel32.GetCurrentProcess();fn=ctypes.windll.psapi.GetProcessMemoryInfo;fn.argtypes=[ctypes.c_void_p,ctypes.POINTER(PMC),ctypes.c_ulong];fn.restype=ctypes.c_int
  if not fn(h,ctypes.byref(z),z.cb):raise OSError('GetProcessMemoryInfo failed')
  return {'pid':os.getpid(),'peak_working_set_MB_this_finalizer':z.PeakWorkingSetSize/1048576,'working_set_MB_this_finalizer':z.WorkingSetSize/1048576,'not_full_task_peak':True}
 except Exception as e:return {'error':repr(e),'full_task_peak_MB':None}
